  1→import { useState, useCallback, useRef, useEffect } from "react";
  2→import { useAuth } from "@/hooks/useAuth";
  3→import { usePlatformConfig } from "@/hooks/usePlatformConfig";
  4→import { supabase } from "@/integrations/supabase/client";
  5→import { Button } from "@/components/ui/button";
  6→import { Textarea } from "@/components/ui/textarea";
  7→import { Checkbox } from "@/components/ui/checkbox";
  8→import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
  9→import { Badge } from "@/components/ui/badge";
 10→import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
 11→import { Progress } from "@/components/ui/progress";
 12→import {
 13→  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
 14→  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle
 15→} from "@/components/ui/alert-dialog";
 16→import { toast } from "sonner";
 17→import {
 18→  Upload, Copy, Loader2, FileText,
 19→  AlertTriangle, X, Trash2, RefreshCw, CheckCircle2, FileSpreadsheet,
 20→  Brain, ListChecks, BarChart2, ArrowRight, Sparkles, Clock, Users, Star, Mail, Zap,
 21→  Archive, ArchiveRestore, FolderOpen
 22→} from "lucide-react";
 23→import { exportToCSV } from "@/lib/csvExport";
 24→import CandidateRow from "@/components/CandidateRow";
 25→import JdQualityBadge from "@/components/JdQualityBadge";
 26→import JdInsightsPanel from "@/components/JdInsightsPanel";
 27→import type { PastJob, Result, ExistingResume } from "@/pages/Index";
 28→
 29→interface JobDetailViewProps {
 30→  selectedJobId: string | null;
 31→  selectedJob: PastJob | null;
 32→  results: Result[];
 33→  setResults: (results: Result[] | ((prev: Result[]) => Result[])) => void;
 34→  existingResumes: ExistingResume[];
 35→  setExistingResumes: (resumes: ExistingResume[] | ((prev: ExistingResume[]) => ExistingResume[])) => void;
 36→  onJobCreated: (job: PastJob) => void;
 37→  onAuthRequired: () => void;
 38→  onJobUpdated?: (jobId: string, updates: Partial<PastJob>) => void;
 39→  isAuthenticated?: boolean;
 40→}
 41→
 42→interface UploadedFile {
 43→  file: File;
 44→  name: string;
 45→}
 46→
 47→const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
 48→
 49→const JobDetailView = ({
 50→  selectedJobId,
 51→  selectedJob,
 52→  results,
 53→  setResults,
 54→  existingResumes,
 55→  setExistingResumes,
 56→  onJobCreated,
 57→  onAuthRequired,
 58→  onJobUpdated,
 59→  isAuthenticated = true,
 60→}: JobDetailViewProps) => {
 61→  const { user, profile, refreshProfile } = useAuth();
 62→  const { data: config } = usePlatformConfig();
 63→
 64→  const [jobDescription, setJobDescription] = useState("");
 65→  const [files, setFiles] = useState<UploadedFile[]>([]);
 66→  const [ranking, setRanking] = useState(false);
 67→  const [rankingProgress, setRankingProgress] = useState(0);
 68→  const [scoredCount, setScoredCount] = useState(0);
 69→  const [totalToScore, setTotalToScore] = useState(0);
 70→  const [expandedRows, setExpandedRows] = useState<Set<string>>(new Set());
 71→  const [dragOver, setDragOver] = useState(false);
 72→  const [rankingError, setRankingError] = useState<{ type: "credits" | "rate_limit" | "generic"; message: string } | null>(null);
 73→  const [validationErrors, setValidationErrors] = useState<string[]>([]);
 74→  const [selectedResumes, setSelectedResumes] = useState<Set<string>>(new Set());
 75→  const [deleteConfirm, setDeleteConfirm] = useState<{type: "single" | "bulk"; resumeId?: string; filePath?: string | null;} | null>(null);
 76→  const [deleting, setDeleting] = useState(false);
 77→  const [analyzingJd, setAnalyzingJd] = useState(false);
 78→  const [dismissedResumes, setDismissedResumes] = useState<Set<string>>(() => new Set());
 79→  const [showArchived, setShowArchived] = useState(false);
 80→
 81→  const resultsRef = useRef<HTMLDivElement>(null);
 82→  const rankingFilesRef = useRef<Set<string>>(new Set());
 83→  const maxResumes = config?.max_resumes_per_job ?? 10;
 84→  const maxFileSizeMb = config?.max_file_size_mb ?? 5;
 85→
 86→  const isNewJobMode = selectedJobId === null;
 87→  const isExistingJob = selectedJobId !== null && selectedJob !== null;
 88→
 89→  const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
 90→  const formatCandidateName = (filename: string) => {
 91→    const name = filename.replace(/\.\w+$/, "");
 92→    if (UUID_REGEX.test(name)) return `Candidate`;
 93→    return name.replace(/[-_]/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
 94→  };
 95→
 96→  // Merge unranked resumes
 97→  const resultResumeIds = new Set(results.map((r) => r.resume_id));
 98→  const pendingResumes: Result[] = existingResumes
 99→    .filter((r) => !resultResumeIds.has(r.id))
100→    .map((r) => ({
101→      id: `pending-${r.id}`,
102→      resume_id: r.id,
103→      overall_score: 0,
104→      missing_skills: [], summary: null, interview_questions: null,
105→      filename: r.filename, file_path: r.file_path, candidate_name: r.candidate_name,
106→      pending: true,
107→    }));
108→  const allResults = [...results, ...pendingResumes];
109→
110→  // Selection helpers
111→  const toggleSelectResume = (resumeId: string) => {
112→    setSelectedResumes((prev) => {
113→      const next = new Set(prev);
114→      if (next.has(resumeId)) next.delete(resumeId); else next.add(resumeId);
115→      return next;
116→    });
117→  };
118→  const toggleSelectAll = () => {
119→    if (selectedResumes.size === allResults.length) setSelectedResumes(new Set());
120→    else setSelectedResumes(new Set(allResults.map((r) => r.resume_id)));
121→  };
122→
123→  // Delete logic
124→  const deleteResume = async (resumeId: string, filePath: string | null) => {
125→    if (filePath) await supabase.storage.from("resumes").remove([filePath]);
126→    await supabase.from("results").delete().eq("resume_id", resumeId);
127→    await supabase.from("resumes").delete().eq("id", resumeId);
128→    setResults((prev: Result[]) => prev.filter((r) => r.resume_id !== resumeId));
129→    setExistingResumes((prev: ExistingResume[]) => prev.filter((r) => r.id !== resumeId));
130→    setSelectedResumes((prev) => { const next = new Set(prev); next.delete(resumeId); return next; });
131→  };
132→
133→  const handleDeleteConfirm = async () => {
134→    if (!deleteConfirm) return;
135→    setDeleting(true);
136→    try {
137→      if (deleteConfirm.type === "single" && deleteConfirm.resumeId) {
138→        await deleteResume(deleteConfirm.resumeId, deleteConfirm.filePath ?? null);
139→        toast.success("Resume deleted");
140→      } else if (deleteConfirm.type === "bulk") {
141→        const toDelete = allResults.filter((r) => selectedResumes.has(r.resume_id));
142→        for (const r of toDelete) await deleteResume(r.resume_id, r.file_path);
143→        toast.success(`${toDelete.length} resume(s) deleted`);
144→      }
145→    } catch { toast.error("Failed to delete"); }
146→    finally { setDeleting(false); setDeleteConfirm(null); }
147→  };
148→
149→  // File handling
150→  const handleFileDrop = useCallback((e: React.DragEvent) => {
151→    e.preventDefault(); setDragOver(false);
152→    const dropped = Array.from(e.dataTransfer.files).filter(
153→      (f) => f.type === "application/pdf" || f.type === "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
154→    );
155→    addFiles(dropped);
156→  }, [files, maxResumes, maxFileSizeMb]);
157→
158→  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
159→    if (e.target.files) addFiles(Array.from(e.target.files));
160→  };
161→
162→  const addFiles = (newFiles: File[]) => {
163→    const currentCount = isExistingJob ? existingResumes.length + files.length : files.length;
164→    const valid = newFiles.filter((f) => {
165→      if (f.size > maxFileSizeMb * 1024 * 1024) { toast.error(`${f.name} exceeds ${maxFileSizeMb}MB limit`); return false; }
166→      return true;
167→    });
168→    const remaining = maxResumes - currentCount;
169→    if (valid.length > remaining) toast.error(`Max ${maxResumes} resumes per job`);
170→    const toAdd = valid.slice(0, Math.max(0, remaining)).map((f) => ({ file: f, name: f.name }));
171→    setFiles((prev) => [...prev, ...toAdd]);
172→  };
173→
174→  const removeFile = (index: number) => setFiles((prev) => prev.filter((_, i) => i !== index));
175→  const toggleRow = (id: string) => {
176→    setExpandedRows((prev) => { const next = new Set(prev); if (next.has(id)) next.delete(id); else next.add(id); return next; });
177→  };
178→
179→  const copyInboxEmail = () => {
180→    if (profile?.inbox_email) { navigator.clipboard.writeText(profile.inbox_email); toast.success("Inbox email copied!"); }
181→  };
182→
183→  const validate = (): string[] => {
184→    const errors: string[] = [];
185→    if (isNewJobMode && !jobDescription.trim()) errors.push("Job description is required.");
186→    const filesToCheck = files.filter(f => !rankingFilesRef.current.has(f.name));
187→    if (filesToCheck.length === 0) errors.push("Upload at least one resume.");
188→    const splitTotal = (profile?.subscription_credits ?? 0) + (profile?.topup_credits ?? 0);
189→    const totalCredits = splitTotal > 0 ? splitTotal : (profile?.credits ?? 0);
190→    if (user && totalCredits < Math.min(filesToCheck.length, 20)) {
191→      errors.push(`Not enough credits. You need ${Math.min(filesToCheck.length, 20)} but have ${totalCredits}.`);
192→    }
193→    return errors;
194→  };
195→
196→  // ── Analyze JD ──────────────────────────────────────────────
197→  const analyzeJd = async (jobId: string) => {
198→    setAnalyzingJd(true);
199→    try {
200→      const response = await fetch(
201→        `https://zkzontawprihrzpayeam.supabase.co/functions/v1/analyze-jd`,
202→        {
203→          method: "POST",
204→          headers: {
205→            "Content-Type": "application/json",
206→            Authorization: `Bearer ${(await supabase.auth.getSession()).data.session?.access_token}`,
207→          },
208→          body: JSON.stringify({ job_id: jobId }),
209→        }
210→      );
211→      if (!response.ok) {
212→        const err = await response.json().catch(() => ({}));
213→        throw new Error(err.error || "JD analysis failed");
214→      }
215→      const data = await response.json();
216→      if (onJobUpdated) {
217→        onJobUpdated(jobId, {
218→          jd_analysis_json: data.jd_analysis,
219→          dynamic_weights_json: data.dynamic_weights,
220→        });
221→      }
222→      return data;
223→    } catch (err: any) {
224→      toast.error(err.message || "JD analysis failed");
225→      throw err;
226→    } finally {
227→      setAnalyzingJd(false);
228→    }
229→  };
230→
231→  // ── Load dismissed resumes from localStorage when job changes ──
232→  useEffect(() => {
233→    setShowArchived(false);
234→    if (selectedJobId) {
235→      try {
236→        const stored = localStorage.getItem(`dismissed_${selectedJobId}`);
237→        if (stored) {
238→          setDismissedResumes(new Set(JSON.parse(stored) as string[]));
239→        } else {
240→          setDismissedResumes(new Set());
241→        }
242→      } catch {
243→        setDismissedResumes(new Set());
244→      }
245→    } else {
246→      setDismissedResumes(new Set());
247→    }
248→  }, [selectedJobId]);
249→
250→  // ── Auto-rank ───────────────────────────────────────────────
251→  const autoRankTriggered = useRef(false);
252→  useEffect(() => {
253→    const unrankedFiles = files.filter(f => !rankingFilesRef.current.has(f.name));
254→    if (unrankedFiles.length > 0 && !ranking && !autoRankTriggered.current) {
255→      if (isNewJobMode && !jobDescription.trim()) return;
256→      autoRankTriggered.current = true;
257→      handleRankClick();
258→    }
259→    if (files.length === 0 && !ranking) autoRankTriggered.current = false;
260→  }, [files, ranking, isNewJobMode, jobDescription]);
261→
262→  const handleRankingError = (err: any) => {
263→    const msg: string = err?.message || "Ranking failed.";
264→    if (msg.includes("Insufficient credits") || err?.status === 402) {
265→      setRankingError({ type: "credits", message: "You don't have enough credits to rank these resumes." });
266→    } else if (msg.includes("Rate limit") || err?.status === 429) {
267→      setRankingError({ type: "rate_limit", message: "Too many jobs in a short time. Please wait a minute and try again." });
268→    } else {
269→      setRankingError({ type: "generic", message: msg });
270→      toast.error(msg);
271→    }
272→  };
273→
274→  const handleRankClick = () => {
275→    if (!user) { onAuthRequired(); return; }
276→    setRankingError(null);
277→    const errors = validate();
278→    setValidationErrors(errors);
279→    if (errors.length > 0) return;
280→    if (isExistingJob) handleRankExisting(); else handleRankNew();
281→  };
282→
283→  const handleRankNew = async () => {
284→    if (!user) return;
285→    const filesToRank = [...files];
286→    rankingFilesRef.current = new Set(filesToRank.map(f => f.name));
287→    setRanking(true); setResults([]); setRankingError(null);
288→    setRankingProgress(5); setScoredCount(0); setTotalToScore(filesToRank.length);
289→
290→    try {
291→      const autoTitle = (() => {
292→        const firstLine = jobDescription.trim().split("\n")[0].trim();
293→        return firstLine.slice(0, 50).trim() || `Job - ${new Date().toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}`;
294→      })();
295→
296→      const { data: job, error: jobError } = await supabase
297→        .from("jobs")
298→        .insert({ user_id: user.id, job_description: jobDescription, status: "pending", title: autoTitle } as any)
299→        .select("id, inbox_email")
300→        .single();

300→        .single();
301→      if (jobError || !job) throw new Error(jobError?.message || "Failed to create job");
302→      setRankingProgress(10);
303→
304→      const analysisData = await analyzeJd(job.id);
305→      setRankingProgress(25);
306→
307→      onJobCreated({
308→        id: job.id,
309→        title: autoTitle,
310→        job_description: jobDescription,
311→        status: "processing",
312→        created_at: new Date().toISOString(),
313→        resume_count: filesToRank.length,
314→        jd_analysis_json: analysisData.jd_analysis,
315→        dynamic_weights_json: analysisData.dynamic_weights,
316→        inbox_email: job.inbox_email ?? null,
317→      });
318→
319→      const resumeIds = await uploadFilesFromSnapshot(job.id, filesToRank);
320→      setRankingProgress(40);
321→
322→      await rankAndPoll(job.id, resumeIds);
323→
324→      setJobDescription("");
325→      setFiles(prev => prev.filter(f => !rankingFilesRef.current.has(f.name)));
326→      toast.success("Candidates ranked!");
327→    } catch (err: any) {
328→      handleRankingError(err);
329→    } finally {
330→      rankingFilesRef.current = new Set();
331→      setRanking(false); setRankingProgress(0); setScoredCount(0); setTotalToScore(0);
332→      autoRankTriggered.current = false;
333→    }
334→  };
335→
336→  const handleRankExisting = async () => {
337→    if (!user || !selectedJobId) return;
338→    const filesToRank = [...files];
339→    rankingFilesRef.current = new Set(filesToRank.map(f => f.name));
340→    setRanking(true); setRankingError(null);
341→    setRankingProgress(10); setScoredCount(0); setTotalToScore(filesToRank.length);
342→
343→    try {
344→      if (!selectedJob?.jd_analysis_json) {
345→        await analyzeJd(selectedJobId);
346→        setRankingProgress(25);
347→      }
348→
349→      const resumeIds = await uploadFilesFromSnapshot(selectedJobId, filesToRank);
350→      setRankingProgress(40);
351→
352→      await rankAndPoll(selectedJobId, resumeIds);
353→
354→      const { data: allResumes } = await supabase
355→        .from("resumes")
356→        .select("id, filename, file_path, candidate_name, created_at")
357→        .eq("job_id", selectedJobId)
358→        .order("created_at", { ascending: false });
359→      if (allResumes) setExistingResumes(allResumes);
360→
361→      setFiles(prev => prev.filter(f => !rankingFilesRef.current.has(f.name)));
362→      toast.success("New resumes ranked!");
363→    } catch (err: any) {
364→      handleRankingError(err);
365→    } finally {
366→      rankingFilesRef.current = new Set();
367→      setRanking(false); setRankingProgress(0); setScoredCount(0); setTotalToScore(0);
368→      autoRankTriggered.current = false;
369→    }
370→  };
371→
372→  const uploadFilesFromSnapshot = async (jobId: string, filesToUpload: UploadedFile[]): Promise<string[]> => {
373→    if (!user) return [];
374→    const resumeIds: string[] = [];
375→    for (const { file, name } of filesToUpload) {
376→      const filePath = `${user.id}/${jobId}/${Date.now()}_${name}`;
377→      const { error: uploadError } = await supabase.storage.from("resumes").upload(filePath, file);
378→      if (uploadError) throw new Error(`Upload failed: ${uploadError.message}`);
379→      const { data: resume, error: resumeError } = await supabase
380→        .from("resumes")
381→        .insert({ job_id: jobId, filename: name, file_path: filePath })
382→        .select("id")
383→        .single();
384→      if (resumeError || !resume) throw new Error(resumeError?.message || "Failed to save resume");
385→      resumeIds.push(resume.id);
386→    }
387→    return resumeIds;
388→  };
389→
390→  const rankAndPoll = async (jobId: string, resumeIds: string[]) => {
391→    const response = await fetch(
392→      `https://zkzontawprihrzpayeam.supabase.co/functions/v1/rank-resumes`,
393→      {
394→        method: "POST",
395→        headers: {
396→          "Content-Type": "application/json",
397→          Authorization: `Bearer ${(await supabase.auth.getSession()).data.session?.access_token}`,
398→        },
399→        body: JSON.stringify({ job_id: jobId, resume_ids: resumeIds }),
400→      }
401→    );
402→
403→    if (!response.ok) {
404→      const errBody = await response.json().catch(() => ({}));
405→      const err: any = new Error(errBody.error || "Ranking failed");
406→      err.status = response.status;
407→      throw err;
408→    }
409→    setRankingProgress(60);
410→
411→    for (let i = 0; i < 150; i++) {
412→      await new Promise((r) => setTimeout(r, 2000));
413→      const { data: resumeProgress } = await supabase.from("resumes").select("id, status").in("id", resumeIds);
414→      if (resumeProgress) {
415→        const done = resumeProgress.filter((r: any) => r.status === "done" || r.status === "failed").length;
416→        setScoredCount(done);
417→        const pct = resumeIds.length > 0 ? Math.round((done / resumeIds.length) * 35) : 0;
418→        setRankingProgress(Math.min(60 + pct, 95));
419→      }
420→
421→      const { data: jobData } = await supabase.from("jobs").select("status").eq("id", jobId).single();
422→      if (jobData?.status === "completed") {
423→         const { data: allResumes } = await supabase.from("resumes").select("id, filename, file_path, candidate_name, parsed_json").eq("job_id", jobId);
424→         if (allResumes) {
425→           const allResumeIds = allResumes.map((r: any) => r.id);
426→            const { data: resultData } = await supabase
427→              .from("results")
428→              .select("id, resume_id, overall_score, missing_skills, summary, interview_questions, hard_fit, category_scores_json, confidence, strengths_json, gaps_json, explanation_json, matched_must_haves, missing_must_haves, scoring_version")
429→              .in("resume_id", allResumeIds);
430→
431→            const resumeMap = new Map(allResumes.map((r: any) => [r.id, r]));
432→            const merged: Result[] = (resultData ?? []).map((r: any) => {
433→              const resume = resumeMap.get(r.resume_id);
434→              const parsed = resume?.parsed_json as any;
435→              return {
436→                ...r,
437→                overall_score: r.overall_score ?? 0,
438→                missing_skills: r.missing_skills ?? [],
439→                filename: resume?.filename ?? "Unknown",
440→                file_path: resume?.file_path ?? null,
441→                candidate_name: resume?.candidate_name ?? null,
442→                candidate_email: parsed?.email ?? parsed?.contact?.email ?? null,
443→                candidate_phone: parsed?.phone ?? parsed?.contact?.phone ?? null,
444→                candidate_location: parsed?.location ?? parsed?.contact?.location ?? null,
445→              };
446→            });
447→          merged.sort((a, b) => b.overall_score - a.overall_score);
448→          setResults(merged);
449→        }
450→        setRankingProgress(100);
451→        await refreshProfile();
452→        setTimeout(() => { resultsRef.current?.scrollIntoView({ behavior: "smooth", block: "start" }); }, 200);
453→        return;
454→      }
455→      if (jobData?.status === "failed") throw new Error("Ranking failed on server");
456→    }
457→    throw new Error("Ranking timed out");
458→  };
459→
460→  const handleRerank = async () => {
461→    if (!user || !selectedJobId || existingResumes.length === 0) return;
462→    setRanking(true); setRankingProgress(10);
463→    try {
464→      if (!selectedJob?.jd_analysis_json) {
465→        await analyzeJd(selectedJobId);
466→        setRankingProgress(20);
467→      }
468→      const resumeIds = existingResumes.map((r) => r.id);
469→      await supabase.from("results").delete().in("resume_id", resumeIds);
470→      for (const rid of resumeIds) {
471→        await supabase.from("resumes").update({ parsed_text: null, parsed_json: null } as any).eq("id", rid);
472→      }
473→      setResults([]); setRankingProgress(30);
474→      await supabase.from("jobs").update({ status: "processing" }).eq("id", selectedJobId);
475→      await rankAndPoll(selectedJobId, resumeIds);
476→      const { data: allResumes } = await supabase
477→        .from("resumes")
478→        .select("id, filename, file_path, candidate_name, created_at")
479→        .eq("job_id", selectedJobId)
480→        .order("created_at", { ascending: false });
481→      if (allResumes) setExistingResumes(allResumes);
482→      toast.success("All candidates re-ranked!");
483→    } catch (err: any) { toast.error(err.message || "Re-ranking failed."); }
484→    finally { setRanking(false); setRankingProgress(0); }
485→  };
486→
487→  const downloadResume = async (filePath: string, filename: string) => {
488→    const { data, error } = await supabase.storage.from("resumes").download(filePath);
489→    if (error || !data) { toast.error("Download failed"); return; }
490→    const url = URL.createObjectURL(data);
491→    const a = document.createElement("a"); a.href = url; a.download = filename; a.click();
492→    URL.revokeObjectURL(url);
493→  };
494→
495→  const deleteCount = deleteConfirm?.type === "bulk" ? selectedResumes.size : 1;
496→
497→  const handleDismiss = (resumeId: string) => {
498→    setDismissedResumes((prev) => {
499→      const next = new Set(prev).add(resumeId);
